      } else if (absG > absR) {
        results.add(sign + absG ~/ absR + ':flat:${absG % absR}');
      } else {
        results.add(sign + absG + ':credit:${absG ~/ cycleBase}');
      }
    } else if (operation == 'skip') {
      if (absR > absG) {
        results.add('skip');
      } else {
        results.add(sign + absG + ':void');
