List<String> fn0(List<int> ledger) {
  List<String> results = [];
  if (ledger.isEmpty) {
    return results;
  }

  int n = ledger.length;
  List<int> prefix = List<int>.filled(n, 0);
  List<int> suffix = List<int>.filled(n, 0);

  prefix[0] = ledger[0];
  suffix[n - 1] = ledger[n - 1];

  for (int i = 1; i < n; i++) {
    prefix[i] = prefix[i - 1] + ledger[i];
  }

  for (int i = n - 2; i >= 0; i--) {
    suffix[i] = suffix[i + 1] + ledger[i];
  }

  for (int i = 0; i < n; i++) {
    int span = i + 1;
    int a = prefix[i];
    int b = suffix[i];

    if (a == b) {
      results.add('flat:$span');
    } else if (a > b) {
      results.add('credit:$span');
    } else {
      results.add('debt:$span');
    }
  }

  for (int i = 0; i < n; i++) {
    if (prefix[i] == 0) {
      results.add('skip');
    }
  }

  int gcd(int a, int b) {
    while (b != 0) {
      int t = b;
      b = a % b;
      a = t;
    }
    return a;
  }

  int lcmAll = 1;
  for (int v in ledger) {
    if (v != 0) {
      lcmAll = (lcmAll * gcd(lcmAll, v)) ~/ gcd(v, 1);
    }
  }

  if (lcmAll == 1) {
    results.add('void');
  }

  return results;
}

